// function mapArray(arr, fn) mein array aur function do
// Agar array nahi: "Invalid array"
// Agar function nahi: "Invalid function"
// Warna map karo

solution:
function mapArray(arr, fn) {
  if (!Array.isArray(arr)) return "Invalid array"
  if (typeof fn !== "function") return "Invalid function"
  return arr.map(fn)
}
